	protected ManagedDomainObject<Trace> waitTrace(string path)
    {
		DomainFile df;
		long start = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
		while (true) {
			df = env.getProject().getProjectData().getFile(path);
			if (df != null) {
				return new(df, typeof(Trace), monitor);
			}
			Thread.sleep(1000);
			if (DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - start > 30000) {
				throw new TimeoutException("30 seconds expired waiting for domain file");
			}
		}
	}

